	t.Setenv("ENTIRE_AUTH_BASE_URL", "http://127.0.0.1:8787")
	c := NewClient(nil, false)
	if !c.inner.AllowInsecureHTTP {
		t.Fatal("NewClient(nil, false) AllowInsecureHTTP = false for loopback, want true")
	}
