func TestIsLoopbackHTTP(t *testing.T) {
	t.Parallel()

	cases := []struct {
		in   string
		want bool
	}{
		{"http://localhost:8080", true},
		{"http://127.0.0.1", true},
		{"http://[::1]:8080", true},
		{"https://localhost", false},     // https never qualifies
		{"http://entire.io", false},      // public host
		{"http://[::1]:8080/path", true}, // path doesn't matter for the host check
		{"", false},
		{"not a url", false},
